async function cepParaLatLong(cep) {
  // 1. Busca endereço no ViaCEP
  cep = cep.replace("-", "");
  const dados = await this.helpers.httpRequest({
    method: "GET",
    url: `https://viacep.com.br/ws/${cep}/json/`,
    json: true,
  });

  if (dados.erro) {
    throw new Error(`CEP ${cep} não encontrado`);
  }

  const endereco = `${dados.logradouro}, ${dados.localidade}, ${dados.uf}, Brasil`;

  // 2. Geocodifica no Nominatim
  const resultados = await this.helpers.httpRequest({
    method: "GET",
    url: "https://nominatim.openstreetmap.org/search",
    qs: {
      q: endereco,
      format: "json",
      limit: "1",
    },
    headers: { "User-Agent": "meu-projeto-faculdade/1.0" }, // obrigatório!
    json: true,
  });

  console.log("Calculando distância.....");
  await new Promise((resolve) => setTimeout(resolve, 1000)); // respeitar rate limit do Nominatim (1 req/s)

  if (!resultados.length) {
    throw new Error(`Endereço não geocodificado: ${endereco}`);
  }

  const lat = parseFloat(resultados[0].lat);
  const lon = parseFloat(resultados[0].lon);
  return { lat, lon };
}

async function calcularRota(cepOrigem, cepDestino) {
  const { lat: lat1, lon: lon1 } = await cepParaLatLong.call(this, cepOrigem);
  const { lat: lat2, lon: lon2 } = await cepParaLatLong.call(this, cepDestino);

  // OSRM espera lon,lat (invertido!)
  console.log("Calculando distância.....");
  const url =
    `https://router.project-osrm.org/route/v1/driving/` +
    `${lon1},${lat1};${lon2},${lat2}` +
    `?overview=full&geometries=geojson`;

  const dados = await this.helpers.httpRequest({
    method: "GET",
    url,
    qs: { overview: "full", geometries: "geojson" },
    json: true,
  });

  if (dados.code !== "Ok") {
    throw new Error(`Erro ao calcular rota: ${dados.message || dados.code}`);
  }

  const rota = dados.routes[0];

  return {
    distancia_km: rota.distance / 1000,
    duracao_min: rota.duration / 60,
    geometria: rota.geometry, // GeoJSON LineString da rota
    origem: { lat: lat1, lon: lon1 },
    destino: { lat: lat2, lon: lon2 },
  };
}

// Uso
const cep1 = $input.first().json['CEP de Origem'];
const cep2 = $input.first().json['CEP de Destino'];
const resultado = await calcularRota.call(this, cep1, cep2);

console.log(`Distância: ${resultado.distancia_km.toFixed(1)} km`);
console.log(`Duração: ${resultado.duracao_min.toFixed(0)} min`);

return [{ json: resultado }];

